#!/usr/bin/env bash
# The two tables of benchmark/status.md §2, from one command.
#
#   scripts/bench-status.sh [options passed straight through]
#
# Builds the release binary and the harness, then runs the harness. Every
# option is the harness's own; `scripts/bench-status.sh --help` lists them.
#
# This script exists so the report can be regenerated by typing one line
# rather than by remembering a corpus path, a thread count and a build. The
# measurements themselves live in crates/rgx-core/examples/status_table.rs,
# which is where the gate, the interleaving and the floor are implemented and
# documented.
#
# Nothing is written into the repository: the transcript goes to the system
# temp directory and the path is printed at the end, so a run can be pasted
# into benchmark/status.md or filed without dirtying the tree.
#
# 3-way comparison: rg vs rgx (in-house, no external engine crates) vs
# rgx-mod (the previous build with grep-regex / grep-searcher, preserved as
# `target/release/rgx-mod.exe`). The baseline lives on the
# `baseline/grep-deps` branch and is rebuilt into rgx-mod.exe from there --
# this script does NOT touch it. To run the 3-way bench:
#
#   git checkout baseline/grep-deps
#   cargo build --release --bin rgx
#   cp target/release/rgx.exe /path/to/post-sota/target/release/rgx-mod.exe
#   git checkout post-sota
#   cargo build --release --bin rgx
#   bash scripts/bench-status.sh --rgx-base target/release/rgx-mod.exe
#
# The 3-way run answers "did removing grep-regex / grep-searcher make rgx
# slower?" -- the answer in the current tree is no, every base/rgx row sits
# inside the 3% floor or in the overlap zone.

set -u

HERE=$(cd "$(dirname "$0")" && pwd)
ROOT=$(cd "$HERE/.." && pwd)
cd "$ROOT" || exit 2

# A stale binary would silently measure the wrong engine, and a stale
# harness would silently apply the wrong gate. Both are rebuilt.
echo "== building rgx (release) =="
cargo build --release --bin rgx || exit 2
echo "== building the harness =="
cargo build --release -p rgx-core --example status_table || exit 2

STAMP=$(date +%Y%m%d-%H%M%S)
OUT="${RGX_STATUS_OUT:-${TMPDIR:-/tmp}/rgx-status-$STAMP.md}"

RGX="$ROOT/target/release/rgx.exe"
[ -x "$RGX" ] || RGX="$ROOT/target/release/rgx"

"$ROOT/target/release/examples/status_table" --out "$OUT" "$@"
RC=$?

echo
echo "transcript: $OUT"
exit $RC
